from argon2.exceptions import VerifyMismatchError
import openpyxl
from openpyxl.styles import Font, PatternFill

TZ = ZoneInfo('Asia/Ho_Chi_Minh')
BASE = os.path.dirname(os.path.abspath(__file__))
DB_PATH = os.environ.get('BT_DB_PATH') or os.path.join(BASE, '..', 'ban-tru.db')
SECURE_COOKIE = os.environ.get('BT_SECURE_COOKIE') == '1'
ph = PasswordHasher()
app = FastAPI(title='Bán trú thông minh')
_BT_SCHEMAS = ["-- Bán trú thông minh — Giai đoạn 2: nền tảng tài khoản, vai trò, phiên, nhật ký\n-- Cấu trúc bám Mục 10 của đề án; các bảng nghiệp vụ (lớp, học sinh, báo nghỉ, chốt suất)\n-- sẽ bổ sung ở đúng giai đoạn của chúng (GĐ3–GĐ5).\nPRAGMA foreign_keys = ON;\n\nCREATE TABLE IF NOT EXISTS roles (\n  code TEXT PRIMARY KEY,\n  name TEXT NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS users (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  username TEXT NOT NULL UNIQUE,\n  full_name TEXT NOT NULL,\n  phone TEXT,\n  password_hash TEXT NOT NULL,\n  must_change_pw INTEGER NOT NULL DEFAULT 1,\n  status TEXT NOT NULL DEFAULT 'active',        -- active | locked\n  failed_count INTEGER NOT NULL DEFAULT 0,\n  locked_until TEXT,\n  created_at TEXT NOT NULL,\n  last_login_at TEXT\n);\n\nCREATE TABLE IF NOT EXISTS user_roles (\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  role_code TEXT NOT NULL REFERENCES roles(code),\n  scope_class_code TEXT,                        -- phạm vi lớp cho GVCN (vd '2A1'); NULL = không giới hạn theo lớp\n  PRIMARY KEY (user_id, role_code)\n);\n\nCREATE TABLE IF NOT EXISTS sessions (\n  token_hash TEXT PRIMARY KEY,\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  created_at TEXT NOT NULL,\n  last_seen_at TEXT NOT NULL,\n  expires_at TEXT NOT NULL,\n  ip TEXT,\n  user_agent TEXT\n);\n\nCREATE TABLE IF NOT EXISTS audit_logs (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts TEXT NOT NULL,\n  user_id INTEGER,\n  username TEXT,\n  action TEXT NOT NULL,                          -- login_ok | login_fail | login_locked | logout | pw_change | pw_reset | user_create | user_status\n  result TEXT NOT NULL,                          -- ok | fail\n  detail TEXT,\n  ip TEXT\n);\n\nCREATE TABLE IF NOT EXISTS settings (\n  key TEXT PRIMARY KEY,\n  value TEXT NOT NULL\n);\n\nINSERT OR IGNORE INTO roles(code, name) VALUES\n  ('admin',   'Quản trị viên'),\n  ('bgh',     'Ban giám hiệu'),\n  ('gvcn',    'Giáo viên chủ nhiệm'),\n  ('bantru',  'Nhân sự bán trú'),\n  ('bep',     'Nhà bếp'),\n  ('phuhuynh','Phụ huynh');\n\nINSERT OR IGNORE INTO settings(key, value) VALUES\n  ('session_idle_minutes', '30'),\n  ('session_absolute_hours', '12'),\n  ('lock_threshold', '5'),\n  ('lock_minutes', '15'),\n  ('pw_min_len', '8');\n", "-- Bán trú thông minh — Giai đoạn 3: danh mục & nhập Excel (Mục 9 + Mục 10 của đề án)\nCREATE TABLE IF NOT EXISTS school_years (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  name TEXT NOT NULL UNIQUE,                  -- vd: 2025-2026\n  is_current INTEGER NOT NULL DEFAULT 0\n);\n\nCREATE TABLE IF NOT EXISTS classes (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  school_year_id INTEGER NOT NULL REFERENCES school_years(id),\n  name TEXT NOT NULL,                          -- vd: 2A1\n  grade INTEGER NOT NULL,                      -- khối 1..5\n  teacher_name TEXT,                           -- họ tên GVCN (hiển thị)\n  UNIQUE(school_year_id, name)\n);\n\nCREATE TABLE IF NOT EXISTS students (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  code TEXT,                                   -- Ma_hoc_sinh (khóa đối chiếu khi có)\n  full_name TEXT NOT NULL,\n  class_id INTEGER NOT NULL REFERENCES classes(id),\n  parent_phone TEXT,                           -- giữ nguyên số 0 đầu (định dạng text)\n  status TEXT NOT NULL DEFAULT 'dang_hoc',     -- dang_hoc | nghi_dai_han | da_chuyen\n  created_at TEXT NOT NULL,\n  updated_at TEXT NOT NULL\n);\nCREATE UNIQUE INDEX IF NOT EXISTS idx_students_code ON students(code) WHERE code IS NOT NULL AND code <> '';\n\nCREATE TABLE IF NOT EXISTS import_jobs (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts TEXT NOT NULL,\n  user_id INTEGER,\n  username TEXT,\n  filename TEXT,\n  status TEXT NOT NULL DEFAULT 'preview',      -- preview | done | cancelled\n  total_rows INTEGER NOT NULL DEFAULT 0,\n  valid_rows INTEGER NOT NULL DEFAULT 0,\n  error_rows INTEGER NOT NULL DEFAULT 0,\n  dup_rows INTEGER NOT NULL DEFAULT 0,\n  imported_rows INTEGER,\n  updated_rows INTEGER,\n  skipped_rows INTEGER,\n  dup_strategy TEXT,\n  rows_json TEXT                               -- các dòng đã đọc kèm nhận định từng dòng (chỉ giữ khi preview)\n);\n", "-- Bán trú thông minh — Giai đoạn 4: liên kết phụ huynh, lịch bán trú, báo nghỉ (Mục 5 + Mục 10)\nCREATE TABLE IF NOT EXISTS parent_students (\n  parent_user_id INTEGER NOT NULL REFERENCES users(id),\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  relation TEXT,                                -- vd: Mẹ, Bố, Ông/Bà...\n  PRIMARY KEY (parent_user_id, student_id)\n);\n\nCREATE TABLE IF NOT EXISTS meal_calendar (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  date TEXT NOT NULL UNIQUE,                    -- YYYY-MM-DD (ngày đặc biệt/ngày nghỉ)\n  serve INTEGER NOT NULL,                       -- 1 có phục vụ, 0 nghỉ\n  cutoff_time TEXT,                             -- hạn riêng cho ngày này (HH:MM), NULL = theo quy tắc tuần\n  note TEXT\n);\n\nCREATE TABLE IF NOT EXISTS meal_absences (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  meal_date TEXT NOT NULL,                      -- YYYY-MM-DD\n  reason TEXT,\n  status TEXT NOT NULL,                         -- dung_han | muon_cho_duyet | muon_da_duyet | muon_tu_choi | da_huy\n  submitted_at TEXT NOT NULL,                   -- giờ máy chủ Asia/Ho_Chi_Minh\n  submitted_by INTEGER NOT NULL REFERENCES users(id),\n  decided_by INTEGER,\n  decided_at TEXT,\n  decision_note TEXT,\n  cancelled_at TEXT\n);\n-- Mỗi học sinh tối đa MỘT báo nghỉ đang có hiệu lực/chờ duyệt cho một ngày ăn (chống trùng cả khi bấm gửi hai lần)\nCREATE UNIQUE INDEX IF NOT EXISTS idx_absence_active\n  ON meal_absences(student_id, meal_date)\n  WHERE status IN ('dung_han', 'muon_cho_duyet', 'muon_da_duyet');\n\nINSERT OR IGNORE INTO settings(key, value) VALUES\n  ('cutoff_default', '08:00'),\n  ('cutoff_wed', ''),                            -- để trống = dùng hạn chung; nhà trường chốt sau (mục 4 Phiếu GĐ1)\n  ('serve_weekdays', '1,2,3,4,5');               -- Thứ Hai..Thứ Sáu (isoweekday)\n", "-- Bán trú thông minh — Giai đoạn 5: chốt suất ăn (Mục 5.4 + Mục 10 của đề án)\n-- Mỗi lần chốt tạo một PHIÊN BẢN mới; mở chốt phải có lý do và được ghi nhật ký.\nCREATE TABLE IF NOT EXISTS meal_closings (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  meal_date TEXT NOT NULL,                      -- YYYY-MM-DD\n  version INTEGER NOT NULL,                     -- 1, 2, 3... theo ngày\n  status TEXT NOT NULL DEFAULT 'closed',        -- closed | reopened\n  closed_by INTEGER NOT NULL REFERENCES users(id),\n  closed_at TEXT NOT NULL,\n  total_meals INTEGER NOT NULL,\n  snapshot_json TEXT NOT NULL,                  -- số liệu từng lớp tại thời điểm chốt\n  reopen_reason TEXT,\n  reopened_by INTEGER,\n  reopened_at TEXT,\n  UNIQUE(meal_date, version)\n);\n", '-- Bán trú thông minh — Giai đoạn 6: thông báo trong ứng dụng (Mục 5.7 của đề án)\nCREATE TABLE IF NOT EXISTS notifications (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  ts TEXT NOT NULL,\n  kind TEXT NOT NULL,                           -- absence_decided | late_submitted | meal_closed | meal_reopened\n  title TEXT NOT NULL,\n  body TEXT,\n  ref_id INTEGER,                               -- id báo nghỉ liên quan (nếu có)\n  is_read INTEGER NOT NULL DEFAULT 0\n);\n', '-- Phòng bán trú (mở rộng 2026-10-26, theo file Bán trú tháng 9.2026 của nhà trường):\n-- Mỗi sheet phòng trong file = 1 phòng do 1 giáo viên trông quản; phòng trộn nhiều lớp.\n-- Học sinh thuộc đúng 1 phòng (students.room_id); chưa xếp phòng = NULL.\nCREATE TABLE IF NOT EXISTS rooms (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  school_year_id INTEGER NOT NULL REFERENCES school_years(id),\n  name TEXT NOT NULL,                  -- vd: C Yến, Ly, C Xuân, Điệp, Đạt, C Mão\n  teacher_name TEXT,                   -- giáo viên trông phòng\n  created_at TEXT NOT NULL,\n  UNIQUE(school_year_id, name)\n);\n', '-- Tiền tháng bán trú (GĐ2 mở rộng 2026-10-26, theo file Bán trú tháng 9.2026):\n-- Mức tháng chung toàn trường (giá suất ăn + tiền trông trưa), trông trưa sửa riêng\n-- từng em được (không sửa = mức chung), nhóm trung tâm từ thiện tính gộp chung,\n-- Ký nộp đánh dấu từng em đã nộp tiền.\nCREATE TABLE IF NOT EXISTS monthly_fees (\n  month TEXT PRIMARY KEY,            -- YYYY-MM\n  meal_price INTEGER NOT NULL DEFAULT 25000,\n  lunch_fee INTEGER NOT NULL DEFAULT 50000,\n  updated_by INTEGER REFERENCES users(id),\n  updated_at TEXT NOT NULL\n);\nCREATE TABLE IF NOT EXISTS fee_overrides (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  month TEXT NOT NULL,\n  lunch_fee INTEGER NOT NULL,\n  updated_by INTEGER REFERENCES users(id),\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY (student_id, month)\n);\nCREATE TABLE IF NOT EXISTS fee_payments (\n  student_id INTEGER NOT NULL REFERENCES students(id),\n  month TEXT NOT NULL,\n  paid INTEGER NOT NULL DEFAULT 0,\n  paid_by INTEGER REFERENCES users(id),\n  paid_at TEXT,\n  PRIMARY KEY (student_id, month)\n);\n', '-- Báo cơm giáo viên (GĐ3 mở rộng 2026-10-26): quản lý nhập số suất cơm giáo\n-- viên theo ngày. Nếu chưa nhập, báo cáo bếp phải ghi rõ "CHƯA BAO GỒM cơm giáo viên".\nCREATE TABLE IF NOT EXISTS teacher_meals (\n  meal_date TEXT PRIMARY KEY,          -- YYYY-MM-DD\n  portions INTEGER NOT NULL,\n  updated_by INTEGER REFERENCES users(id),\n  updated_at TEXT NOT NULL\n);\n', "-- Thực đơn tuần bán trú (thiết kế lại 2026-10-26, thay ảnh mẫu):\n-- Mỗi tuần (khóa = ngày thứ 2 đầu tuần) có 5 ngày Thứ 2–Thứ 6, mỗi ngày 4 món\n-- (món chính, món rau/xào, canh, tráng miệng) + ghi chú. Không giá tiền, không\n-- tính dinh dưỡng (đề án loại trừ 2 khoản này; tiền ăn nằm ở màn hình Tiền tháng).\nCREATE TABLE IF NOT EXISTS menu_days (\n  week_start TEXT NOT NULL,          -- YYYY-MM-DD, ngày thứ 2 đầu tuần\n  weekday INTEGER NOT NULL,          -- 1 = Thứ 2 .. 5 = Thứ 6\n  main_dish TEXT NOT NULL DEFAULT '',\n  veg_dish TEXT NOT NULL DEFAULT '',\n  soup TEXT NOT NULL DEFAULT '',\n  dessert TEXT NOT NULL DEFAULT '',\n  note TEXT NOT NULL DEFAULT '',\n  updated_by INTEGER REFERENCES users(id),\n  updated_at TEXT NOT NULL,\n  PRIMARY KEY (week_start, weekday)\n);\n", '-- Thông báo đẩy kiểu tin nhắn (thầy dặn 26/10): mỗi trình duyệt của phụ huynh\n-- (hoặc nhân viên) đăng ký một subscription; khi nhà trường gửi thông báo,\n-- máy chủ push tới các subscription của người nhận. Khóa VAPID lưu trong bảng\n-- settings (cùng CSDL nên tự bền vững theo CSDL, không cần file riêng).\nCREATE TABLE IF NOT EXISTS push_subscriptions (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  user_id INTEGER NOT NULL REFERENCES users(id),\n  endpoint TEXT NOT NULL,\n  p256dh TEXT NOT NULL,\n  auth TEXT NOT NULL,\n  created_at TEXT NOT NULL,\n  UNIQUE(user_id, endpoint)\n);\n']

def now():
    return datetime.now(TZ)

def db():
    con = sqlite3.connect(DB_PATH)
    con.row_factory = sqlite3.Row
    return con

def init_db():
    con = db()
    for _sql in _BT_SCHEMAS:
        con.executescript(_sql)
    # Di trú cộng thêm: students.room_id (phòng bán trú, mở rộng 2026-10-26).
    cols = [r[1] for r in con.execute('PRAGMA table_info(students)')]
    if 'room_id' not in cols:
        con.execute('ALTER TABLE students ADD COLUMN room_id INTEGER REFERENCES rooms(id)')
    con.execute('CREATE INDEX IF NOT EXISTS idx_students_room ON students(room_id)')
    # Di trú cộng thêm: students.is_charity (nhóm trung tâm từ thiện, GĐ2 2026-10-26).
    cols = [r[1] for r in con.execute('PRAGMA table_info(students)')]
    if 'is_charity' not in cols:
        con.execute('ALTER TABLE students ADD COLUMN is_charity INTEGER NOT NULL DEFAULT 0')
    # Di trú cộng thêm: nhật ký nhập chia phòng (báo cáo sau nhập + hoàn tác, 2026-10-26).
    con.execute('''CREATE TABLE IF NOT EXISTS room_import_log(
        id INTEGER PRIMARY KEY AUTOINCREMENT, school_year_id INTEGER,
        created_at TEXT, username TEXT, snapshot TEXT, skipped TEXT,
        assigned INTEGER DEFAULT 0, rooms_created INTEGER DEFAULT 0,
        undone INTEGER NOT NULL DEFAULT 0)''')
    con.commit(); con.close()

def setting(con, key, default):
    row = con.execute('SELECT value FROM settings WHERE key=?', (key,)).fetchone()
    return row['value'] if row else default

def audit(con, action, result, user=None, username=None, detail='', ip=''):
    con.execute(
        'INSERT INTO audit_logs(ts,user_id,username,action,result,detail,ip) VALUES(?,?,?,?,?,?,?)',
        (now().isoformat(timespec='seconds'), user['id'] if user else None,
         username or (user['username'] if user else None), action, result, detail, ip))

def err(status, code, message):
    return JSONResponse({'ok': False, 'code': code, 'message': message}, status_code=status)

def roles_of(con, user_id):
    return [dict(r) for r in con.execute(
        'SELECT r.code, r.name, ur.scope_class_code FROM user_roles ur '
        'JOIN roles r ON r.code = ur.role_code WHERE ur.user_id=?', (user_id,))]

def public_user(con, user):
    return {'id': user['id'], 'username': user['username'], 'full_name': user['full_name'],
            'phone': user['phone'], 'must_change_pw': bool(user['must_change_pw']),
            'roles': roles_of(con, user['id'])}

# ---------------- Phiên đăng nhập ----------------

def _token_hash(token):
    return hashlib.sha256(token.encode()).hexdigest()

def create_session(con, user_id, req):
    token = secrets.token_urlsafe(32)
    idle = int(setting(con, 'session_idle_minutes', '30'))
    absolute = int(setting(con, 'session_absolute_hours', '12'))
    t = now()
    con.execute('INSERT INTO sessions(token_hash,user_id,created_at,last_seen_at,expires_at,ip,user_agent) '
                'VALUES(?,?,?,?,?,?,?)',
                (_token_hash(token), user_id, t.isoformat(timespec='seconds'),
                 t.isoformat(timespec='seconds'),
                 (t + timedelta(hours=absolute)).isoformat(timespec='seconds'),
                 req.client.host if req.client else '', req.headers.get('user-agent', '')[:120]))
    return token, idle

def current_user(req):
    """Trả (user, session) nếu phiên còn hạn; phiên quá lâu không thao tác sẽ hết hạn."""
    token = req.cookies.get('bt_session')
    if not token:
        return None, None
    con = db()
    s = con.execute('SELECT * FROM sessions WHERE token_hash=?', (_token_hash(token),)).fetchone()
    if not s:
        con.close(); return None, None
    t = now()
    idle = int(setting(con, 'session_idle_minutes', '30'))
    last = datetime.fromisoformat(s['last_seen_at'])
    exp = datetime.fromisoformat(s['expires_at'])
    if t > exp or (t - last) > timedelta(minutes=idle):
        con.execute('DELETE FROM sessions WHERE token_hash=?', (_token_hash(token),))
        con.commit(); con.close(); return None, None
    con.execute('UPDATE sessions SET last_seen_at=? WHERE token_hash=?',
                (t.isoformat(timespec='seconds'), _token_hash(token)))
    con.commit()
    u = con.execute('SELECT * FROM users WHERE id=?', (s['user_id'],)).fetchone()
    con.close()
    if not u or u['status'] != 'active':
        return None, None
    return u, s

def need_user(req):
    u, _ = current_user(req)
    if not u:
        return None, err(401, 'no_session', 'Phiên đăng nhập đã hết hạn. Vui lòng đăng nhập lại.')
    return u, None

def need_live(req):
    """need_user + đã đổi mật khẩu lần đầu (cổng bắt buộc theo đề án Mục 7)."""
    u, e = need_user(req)
    if e: return None, e
    if u['must_change_pw']:
        return None, err(403, 'must_change_password',
                         'Tài khoản đang dùng mật khẩu tạm. Vui lòng đổi mật khẩu trước khi tiếp tục.')
    return u, None

def need_role(req, *codes):
    u, e = need_live(req)
    if e: return None, e
    con = db()
    have = {r['code'] for r in roles_of(con, u['id'])}
    con.close()
    if not (have & set(codes)):
        return None, err(403, 'forbidden', 'Tài khoản không có quyền thực hiện chức năng này.')
    return u, None

# ---------------- Đăng nhập / mật khẩu ----------------

@app.post('/api/login')
async def login(req: Request):
    body = await req.json()
    username = (body.get('username') or '').strip()
    password = body.get('password') or ''
    ip = req.client.host if req.client else ''
    con = db()
    u = con.execute('SELECT * FROM users WHERE username=?', (username,)).fetchone()
    if not u:
        audit(con, 'login_fail', 'fail', username=username, detail='Tài khoản không tồn tại', ip=ip)
        con.commit(); con.close()
        return err(401, 'bad_credentials', 'Tên đăng nhập hoặc mật khẩu chưa đúng.')
    if u['status'] != 'active':
        audit(con, 'login_fail', 'fail', user=u, detail='Tài khoản đã bị khóa bởi quản trị', ip=ip)
        con.commit(); con.close()
        return err(403, 'account_locked', 'Tài khoản đã bị khóa. Vui lòng liên hệ nhà trường.')
    if u['locked_until'] and now() < datetime.fromisoformat(u['locked_until']):
        audit(con, 'login_locked', 'fail', user=u, detail='Đang khóa tạm do sai mật khẩu nhiều lần', ip=ip)
        con.commit(); con.close()
        return err(423, 'temporarily_locked',
                   'Tài khoản tạm khóa do nhập sai nhiều lần. Vui lòng thử lại sau ít phút.')
    try:
        ph.verify(u['password_hash'], password)
    except VerifyMismatchError:
        threshold = int(setting(con, 'lock_threshold', '5'))
        minutes = int(setting(con, 'lock_minutes', '15'))
        fc = u['failed_count'] + 1
        locked_until = None
        if fc >= threshold:
            locked_until = (now() + timedelta(minutes=minutes)).isoformat(timespec='seconds')
            fc = 0
        con.execute('UPDATE users SET failed_count=?, locked_until=? WHERE id=?', (fc, locked_until, u['id']))
        audit(con, 'login_fail', 'fail', user=u,
              detail=('Sai mật khẩu — đã khóa tạm %d phút' % minutes) if locked_until else 'Sai mật khẩu', ip=ip)
        con.commit(); con.close()
        return err(401, 'bad_credentials', 'Tên đăng nhập hoặc mật khẩu chưa đúng.')
    con.execute('UPDATE users SET failed_count=0, locked_until=NULL, last_login_at=? WHERE id=?',
                (now().isoformat(timespec='seconds'), u['id']))
    token, _ = create_session(con, u['id'], req)
    audit(con, 'login_ok', 'ok', user=u, ip=ip)
    con.commit()
    data = public_user(con, con.execute('SELECT * FROM users WHERE id=?', (u['id'],)).fetchone())
    con.close()
    resp = JSONResponse({'ok': True, 'user': data})
    resp.set_cookie('bt_session', token, httponly=True, samesite='lax',
                    secure=SECURE_COOKIE, max_age=12 * 3600, path='/')
    return resp

@app.post('/api/logout')
async def logout(req: Request):
    u, _ = current_user(req)
    token = req.cookies.get('bt_session')
    con = db()
    if token:
        con.execute('DELETE FROM sessions WHERE token_hash=?', (_token_hash(token),))
    if u:
        audit(con, 'logout', 'ok', user=u, ip=req.client.host if req.client else '')
    con.commit(); con.close()
    resp = JSONResponse({'ok': True})
    resp.delete_cookie('bt_session', path='/')
    return resp

@app.get('/api/me')
async def me(req: Request):
    u, e = need_user(req)
    if e: return e
    con = db(); data = public_user(con, u); con.close()
    return {'ok': True, 'user': data}

@app.post('/api/change-password')
async def change_password(req: Request):
    u, e = need_user(req)
    if e: return e
    body = await req.json()
    old = body.get('old_password') or ''
    new = body.get('new_password') or ''
    con = db()
    try:
        ph.verify(u['password_hash'], old)
    except VerifyMismatchError:
        con.close()
        return err(400, 'wrong_old', 'Mật khẩu hiện tại chưa đúng.')
    minlen = int(setting(con, 'pw_min_len', '8'))
    if len(new) < minlen or new == old:
        con.close()
        return err(400, 'weak_new', 'Mật khẩu mới phải có ít nhất %d ký tự và khác mật khẩu hiện tại.' % minlen)
    con.execute('UPDATE users SET password_hash=?, must_change_pw=0 WHERE id=?',
                (ph.hash(new), u['id']))
    # Đổi mật khẩu xong: hủy các phiên khác, giữ phiên hiện tại
    token = req.cookies.get('bt_session')
    con.execute('DELETE FROM sessions WHERE user_id=? AND token_hash<>?', (u['id'], _token_hash(token or '')))
    audit(con, 'pw_change', 'ok', user=u, ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'message': 'Đã đổi mật khẩu thành công.'}

# ---------------- Quản trị tài khoản (vai trò admin) ----------------

def gen_temp_password():
    alpha = string.ascii_letters + string.digits
    while True:
        pw = ''.join(secrets.choice(alpha) for _ in range(10))
        if any(c.isdigit() for c in pw) and any(c.isalpha() for c in pw):
            return pw

@app.get('/api/admin/users')
async def admin_users(req: Request):
    u, e = need_role(req, 'admin')
    if e: return e
    con = db()
    rows = con.execute('SELECT * FROM users ORDER BY id').fetchall()
    out = [dict(public_user(con, r), status=r['status'],
                last_login_at=r['last_login_at'], created_at=r['created_at']) for r in rows]
    con.close()
    return {'ok': True, 'users': out}

@app.post('/api/admin/users')
async def admin_create_user(req: Request):
    u, e = need_role(req, 'admin')
    if e: return e
    body = await req.json()
    username = (body.get('username') or '').strip()
    full_name = (body.get('full_name') or '').strip()
    roles = body.get('roles') or []
    if not username or not full_name or not roles:
        return err(400, 'missing', 'Thiếu tên đăng nhập, họ tên hoặc vai trò.')
    con = db()
    valid = {r['code'] for r in con.execute('SELECT code FROM roles')}
    if not set(roles) <= valid:
        con.close(); return err(400, 'bad_role', 'Có vai trò không hợp lệ.')
    if con.execute('SELECT 1 FROM users WHERE username=?', (username,)).fetchone():
        con.close(); return err(409, 'exists', 'Tên đăng nhập đã tồn tại.')
    temp = gen_temp_password()
    cur = con.execute('INSERT INTO users(username,full_name,phone,password_hash,must_change_pw,created_at) '
                      'VALUES(?,?,?,?,1,?)',
                      (username, full_name, (body.get('phone') or '').strip(),
                       ph.hash(temp), now().isoformat(timespec='seconds')))
    uid = cur.lastrowid
    for rc in roles:
        con.execute('INSERT INTO user_roles(user_id,role_code,scope_class_code) VALUES(?,?,?)',
                    (uid, rc, body.get('scope_class_code') if rc == 'gvcn' else None))
    audit(con, 'user_create', 'ok', user=u, detail='Tạo tài khoản %s (%s)' % (username, ','.join(roles)),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'user_id': uid, 'temp_password': temp,
            'message': 'Đã tạo tài khoản. Mật khẩu tạm chỉ hiển thị lần này — gửi cho người dùng qua kênh an toàn.'}

@app.post('/api/admin/users/{uid}/reset-password')
async def admin_reset_pw(req: Request, uid: int):
    u, e = need_role(req, 'admin')
    if e: return e
    con = db()
    target = con.execute('SELECT * FROM users WHERE id=?', (uid,)).fetchone()
    if not target:
        con.close(); return err(404, 'not_found', 'Không tìm thấy tài khoản.')
    temp = gen_temp_password()
    con.execute('UPDATE users SET password_hash=?, must_change_pw=1, failed_count=0, locked_until=NULL WHERE id=?',
                (ph.hash(temp), uid))
    con.execute('DELETE FROM sessions WHERE user_id=?', (uid,))
    audit(con, 'pw_reset', 'ok', user=u, detail='Đặt lại mật khẩu cho %s' % target['username'],
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'temp_password': temp,
            'message': 'Đã đặt lại mật khẩu tạm. Người dùng sẽ phải đổi mật khẩu ở lần đăng nhập tới.'}

@app.post('/api/admin/users/{uid}/status')
async def admin_set_status(req: Request, uid: int):
    u, e = need_role(req, 'admin')
    if e: return e
    body = await req.json()
    status = body.get('status')
    if status not in ('active', 'locked'):
        return err(400, 'bad_status', 'Trạng thái không hợp lệ.')
    con = db()
    target = con.execute('SELECT * FROM users WHERE id=?', (uid,)).fetchone()
    if not target:
        con.close(); return err(404, 'not_found', 'Không tìm thấy tài khoản.')
    con.execute('UPDATE users SET status=? WHERE id=?', (status, uid))
    if status == 'locked':
        con.execute('DELETE FROM sessions WHERE user_id=?', (uid,))
    audit(con, 'user_status', 'ok', user=u,
          detail='%s tài khoản %s' % ('Khóa' if status == 'locked' else 'Mở khóa', target['username']),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True}

