# ---------------- Giai đoạn 3: Danh mục ----------------

def current_year(con):
    return con.execute('SELECT * FROM school_years WHERE is_current=1').fetchone() \
        or con.execute('SELECT * FROM school_years ORDER BY id LIMIT 1').fetchone()

def gvcn_class_names(con, user_id):
    return [r['scope_class_code'] for r in con.execute(
        "SELECT scope_class_code FROM user_roles WHERE user_id=? AND role_code='gvcn'", (user_id,))
        if r['scope_class_code']]

def student_pub(con, s):
    c = con.execute('SELECT * FROM classes WHERE id=?', (s['class_id'],)).fetchone()
    rid = s['room_id'] if 'room_id' in s.keys() else None
    r = con.execute('SELECT * FROM rooms WHERE id=?', (rid,)).fetchone() if rid else None
    return {'id': s['id'], 'code': s['code'], 'full_name': s['full_name'],
            'class_id': s['class_id'], 'class_name': c['name'] if c else '',
            'grade': c['grade'] if c else None,
            'parent_phone': s['parent_phone'], 'status': s['status'],
            'room_id': rid, 'room_name': r['name'] if r else '',
            'is_charity': (s['is_charity'] if 'is_charity' in s.keys() else 0) or 0}

