@app.get('/api/students')
async def students_list(req: Request, class_id: int = 0, q: str = '', room_id: int = 0):
    u, e = need_role(req, 'admin', 'bgh', 'gvcn', 'bantru')
    if e: return e
    con = db()
    roles = {r['code'] for r in roles_of(con, u['id'])}
    sql = 'SELECT s.* FROM students s JOIN classes c ON c.id=s.class_id WHERE 1=1'
    args = []
    if 'gvcn' in roles and not (roles & {'admin', 'bgh', 'bantru'}):
        names = gvcn_class_names(con, u['id'])
        if not names:
            con.close(); return {'ok': True, 'students': []}
        sql += ' AND c.name IN (%s)' % ','.join('?' * len(names)); args += names
    if class_id:
        sql += ' AND s.class_id=?'; args.append(class_id)
    if room_id:
        sql += ' AND s.room_id=?'; args.append(room_id)
    if q:
        sql += ' AND (s.full_name LIKE ? OR s.code LIKE ?)'; args += ['%' + q + '%', '%' + q + '%']
    sql += ' ORDER BY c.grade, c.name, s.full_name'
    rows = con.execute(sql, args).fetchall()
    out = [student_pub(con, r) for r in rows]
    con.close()
    return {'ok': True, 'students': out}

@app.post('/api/students')
async def students_create(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    name = (body.get('full_name') or '').strip()
    class_id = body.get('class_id')
    phone = (body.get('parent_phone') or '').strip()
    if not name or not class_id:
        return err(400, 'missing', 'Thiếu họ tên học sinh hoặc lớp.')
    if phone and not re.fullmatch(r'0\d{9}', phone):
        return err(400, 'bad_phone', 'Số điện thoại phụ huynh phải gồm 10 chữ số, bắt đầu bằng 0.')
    con = db()
    if not con.execute('SELECT 1 FROM classes WHERE id=?', (class_id,)).fetchone():
        con.close(); return err(400, 'no_class', 'Lớp không tồn tại.')
    code = (body.get('code') or '').strip() or None
    if code and con.execute('SELECT 1 FROM students WHERE code=?', (code,)).fetchone():
        con.close(); return err(409, 'dup_code', 'Mã học sinh %s đã tồn tại.' % code)
    t = now().isoformat(timespec='seconds')
    con.execute('INSERT INTO students(code,full_name,class_id,parent_phone,created_at,updated_at) VALUES(?,?,?,?,?,?)',
                (code, name, class_id, phone or None, t, t))
    audit(con, 'catalog', 'ok', user=u, detail='Thêm học sinh %s' % name, ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True}

@app.patch('/api/students/{sid}')
async def students_update(req: Request, sid: int):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    con = db()
    s = con.execute('SELECT * FROM students WHERE id=?', (sid,)).fetchone()
    if not s:
        con.close(); return err(404, 'not_found', 'Không tìm thấy học sinh.')
    sets, args = [], []
    for field in ('full_name', 'parent_phone', 'status', 'class_id', 'code'):
        if field in body:
            sets.append(field + '=?'); args.append(body[field])
    if 'room_id' in body:
        rid = body['room_id']
        if rid is not None:
            rm = con.execute('SELECT * FROM rooms WHERE id=?', (rid,)).fetchone()
            sc = con.execute('SELECT school_year_id FROM classes WHERE id=?', (s['class_id'],)).fetchone()
            if not rm or not sc or rm['school_year_id'] != sc['school_year_id']:
                con.close(); return err(400, 'bad_room', 'Phòng không tồn tại hoặc không cùng năm học với lớp của học sinh.')
        sets.append('room_id=?'); args.append(rid)
    if 'is_charity' in body:
        v = body['is_charity']
        if v not in (0, 1, True, False):
            con.close(); return err(400, 'bad_charity', 'Cờ nhóm từ thiện chỉ nhận 0 hoặc 1.')
        sets.append('is_charity=?'); args.append(1 if v else 0)
    if 'status' in body and body['status'] not in ('dang_hoc', 'nghi_dai_han', 'da_chuyen'):
        con.close(); return err(400, 'bad_status', 'Trạng thái học sinh không hợp lệ.')
    if sets:
        sets.append('updated_at=?'); args.append(now().isoformat(timespec='seconds')); args.append(sid)
        con.execute('UPDATE students SET %s WHERE id=?' % ', '.join(sets), args)
        audit(con, 'catalog', 'ok', user=u, detail='Cập nhật học sinh #%d (%s)' % (sid, ', '.join(body.keys())),
              ip=req.client.host if req.client else '')
        con.commit()
    con.close()
    return {'ok': True}

