# ---------------- Tiền tháng bán trú (GĐ2 mở rộng 2026-10-26) ----------------
# Công thức đúng file tháng 9: Tiền ăn = số buổi ăn × giá suất ăn (mức tháng chung);
# Trông trưa = mức chung của tháng, sửa riêng từng em được (không sửa = mức chung);
# Tổng tiền = Tiền ăn + Trông trưa. Nhóm trung tâm từ thiện tính GỘP CHUNG 1 tổng,
# không tính theo lớp, không cộng vào Tổng lớp. Số buổi ăn = ngày phục vụ trong
# tháng (theo lịch tuần + lịch đặc biệt) trừ báo nghỉ có hiệu lực (đúng hạn + muộn
# đã duyệt); báo muộn chưa duyệt / bị từ chối / đã hủy không trừ.

def _valid_month(ym):
    if not re.fullmatch(r'\d{4}-\d{2}', ym or ''):
        return False
    return 1 <= int(ym[5:7]) <= 12

def _month_range(ym):
    y, m = int(ym[:4]), int(ym[5:7])
    nxt = '%04d-%02d' % (y + m // 12, m % 12 + 1)
    return '%s-01' % ym, nxt + '-01'

def _served_days(con, ym):
    y, m = int(ym[:4]), int(ym[5:7])
    _, ndays = calendar.monthrange(y, m)
    weekdays = set()
    for t in (setting(con, 'serve_weekdays', '1,2,4,5') or '').split(','):
        t = t.strip()
        if t.isdigit(): weekdays.add(int(t))
    d0, d1 = _month_range(ym)
    cal = {r['date']: r['serve'] for r in con.execute(
        'SELECT * FROM meal_calendar WHERE date>=? AND date<?', (d0, d1))}
    out = []
    for d in range(1, ndays + 1):
        ds = '%04d-%02d-%02d' % (y, m, d)
        serve = cal[ds] if ds in cal else (1 if date(y, m, d).isoweekday() in weekdays else 0)
        if serve: out.append(ds)
    return out

def _fee_month_data(con, ym, scope_classes=None):
    y = current_year(con)
    if not y: return None
    f = con.execute('SELECT * FROM monthly_fees WHERE month=?', (ym,)).fetchone()
    meal_price = f['meal_price'] if f else 25000
    lunch_common = f['lunch_fee'] if f else 50000
    served = _served_days(con, ym)
    d0, d1 = _month_range(ym)
    absmap = {}
    for a in con.execute(
            "SELECT student_id, meal_date FROM meal_absences WHERE status IN ('dung_han','muon_da_duyet') "
            'AND meal_date>=? AND meal_date<?', (d0, d1)):
        absmap.setdefault(a['student_id'], set()).add(a['meal_date'])
    overrides = {r['student_id']: r['lunch_fee'] for r in con.execute(
        'SELECT * FROM fee_overrides WHERE month=?', (ym,))}
    paid = {r['student_id'] for r in con.execute(
        'SELECT * FROM fee_payments WHERE month=? AND paid=1', (ym,))}
    rows = []
    for s in con.execute(
            'SELECT s.*, c.name AS class_name, c.grade FROM students s JOIN classes c ON c.id=s.class_id '
            "WHERE c.school_year_id=? AND s.status='dang_hoc' ORDER BY c.grade, c.name, s.full_name", (y['id'],)):
        if scope_classes is not None and s['class_name'] not in scope_classes:
            continue
        start = max(ym + '-01', (s['created_at'] or '')[:10])
        days = [d for d in served if d >= start]
        eaten = len([d for d in days if d not in absmap.get(s['id'], set())])
        lunch = overrides.get(s['id'], lunch_common)
        meal = eaten * meal_price
        rows.append({'id': s['id'], 'code': s['code'], 'full_name': s['full_name'],
                     'class_name': s['class_name'], 'grade': s['grade'],
                     'is_charity': (s['is_charity'] if 'is_charity' in s.keys() else 0) or 0,
                     'served_days': len(days), 'days': eaten,
                     'meal_price': meal_price, 'meal_fee': meal,
                     'lunch_fee': lunch, 'lunch_override': s['id'] in overrides,
                     'total': meal + lunch, 'paid': s['id'] in paid})
    classes = {}
    for r in rows:
        if r['is_charity']: continue
        c = classes.setdefault(r['class_name'], {'class_name': r['class_name'], 'grade': r['grade'],
                                                 'count': 0, 'days': 0, 'meal_fee': 0, 'lunch_fee': 0, 'total': 0})
        c['count'] += 1; c['days'] += r['days']; c['meal_fee'] += r['meal_fee']
        c['lunch_fee'] += r['lunch_fee']; c['total'] += r['total']
    class_list = sorted(classes.values(), key=lambda c: (c['grade'], c['class_name']))
    charity_rows = [r for r in rows if r['is_charity']]
    charity_total = {'count': len(charity_rows), 'days': sum(r['days'] for r in charity_rows),
                     'meal_fee': sum(r['meal_fee'] for r in charity_rows),
                     'lunch_fee': sum(r['lunch_fee'] for r in charity_rows),
                     'total': sum(r['total'] for r in charity_rows)}
    grand = sum(c['total'] for c in class_list) + charity_total['total']
    return {'month': ym, 'year': y['name'], 'meal_price': meal_price, 'lunch_fee': lunch_common,
            'settings_saved': f is not None, 'rows': rows, 'classes': class_list,
            'charity': charity_total, 'grand_total': grand,
            'student_count': len(rows)}

@app.get('/api/fees/month')
async def fees_month(req: Request, month: str = ''):
    u, e = need_role(req, 'admin', 'bgh', 'bantru', 'gvcn')
    if e: return e
    ym = (month or now().strftime('%Y-%m')).strip()
    if not _valid_month(ym):
        return err(400, 'bad_month', 'Tháng phải có dạng YYYY-MM (tháng 01–12).')
    con = db()
    roles = {r['code'] for r in roles_of(con, u['id'])}
    scope = None
    if 'gvcn' in roles and not (roles & {'admin', 'bgh', 'bantru'}):
        scope = set(gvcn_class_names(con, u['id']))
    data = _fee_month_data(con, ym, scope_classes=scope)
    if not data:
        con.close(); return err(400, 'no_year', 'Chưa có năm học.')
    if scope is not None:
        data['charity'] = None; data['grand_total'] = sum(c['total'] for c in data['classes'])
    con.close()
    return {'ok': True, **data}

@app.post('/api/fees/settings')
async def fees_settings(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    ym = (body.get('month') or '').strip()
    mp, lf = body.get('meal_price'), body.get('lunch_fee')
    if not _valid_month(ym) or not isinstance(mp, int) or not isinstance(lf, int) or mp < 0 or lf < 0:
        return err(400, 'bad_settings', 'Tháng (YYYY-MM) và 2 mức tiền (số nguyên ≥ 0) chưa hợp lệ.')
    con = db()
    t = now().isoformat(timespec='seconds')
    con.execute('INSERT INTO monthly_fees(month,meal_price,lunch_fee,updated_by,updated_at) VALUES(?,?,?,?,?) '
                'ON CONFLICT(month) DO UPDATE SET meal_price=excluded.meal_price, lunch_fee=excluded.lunch_fee, '
                'updated_by=excluded.updated_by, updated_at=excluded.updated_at',
                (ym, mp, lf, u['id'], t))
    audit(con, 'fees', 'ok', user=u, detail='Lưu mức tháng %s: suất ăn %d, trông trưa %d' % (ym, mp, lf),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True}

@app.post('/api/fees/override')
async def fees_override(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    ym = (body.get('month') or '').strip()
    sid, lf = body.get('student_id'), body.get('lunch_fee')
    if not _valid_month(ym) or not sid:
        return err(400, 'bad_override', 'Thiếu tháng hoặc học sinh.')
    con = db()
    y = current_year(con)
    s = con.execute('SELECT s.*, c.school_year_id FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=?',
                    (sid,)).fetchone() if y else None
    if not s or (y and s['school_year_id'] != y['id']):
        con.close(); return err(400, 'bad_student', 'Học sinh không thuộc năm học hiện tại.')
    t = now().isoformat(timespec='seconds')
    if lf is None:
        con.execute('DELETE FROM fee_overrides WHERE student_id=? AND month=?', (sid, ym))
        detail = 'Xóa mức trông trưa riêng tháng %s của HS #%d (về mức chung)' % (ym, sid)
    else:
        if not isinstance(lf, int) or lf < 0:
            con.close(); return err(400, 'bad_override', 'Mức trông trưa riêng phải là số nguyên ≥ 0.')
        con.execute('INSERT INTO fee_overrides(student_id,month,lunch_fee,updated_by,updated_at) VALUES(?,?,?,?,?) '
                    'ON CONFLICT(student_id,month) DO UPDATE SET lunch_fee=excluded.lunch_fee, '
                    'updated_by=excluded.updated_by, updated_at=excluded.updated_at',
                    (sid, ym, lf, u['id'], t))
        detail = 'Sửa mức trông trưa riêng tháng %s của HS #%d thành %d' % (ym, sid, lf)
    audit(con, 'fees', 'ok', user=u, detail=detail, ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True}

