@app.post('/api/students/charity/preview')
async def charity_preview(req: Request, file: UploadFile = File(...)):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    data = await file.read()
    try:
        wb = openpyxl.load_workbook(io.BytesIO(data), read_only=True, data_only=True)
        ws = next((s for s in wb.worksheets if (s.title or '').strip().casefold() == 'tổng hợp'), None)
        if ws is None:
            return err(400, 'no_summary', 'Không tìm thấy sheet Tổng hợp trong file.')
        rows = _room_sheet_rows(ws)
        if rows is None:
            return err(400, 'bad_sheet', 'Không đọc được bảng Tổng hợp trong file.')
    except Exception:
        return err(400, 'bad_file', 'Không đọc được tệp Excel. Hãy kiểm tra lại định dạng .xlsx.')
    seen, boundary = set(), None
    for i, row in enumerate(rows):
        if row['class'] in seen:
            boundary = i; break
        seen.add(row['class'])
    block = rows[boundary:] if boundary is not None else []
    con = db()
    y = current_year(con)
    if not y:
        con.close(); return err(400, 'no_year', 'Chưa có năm học.')
    by_key = {}
    for s in con.execute(
            'SELECT s.*, c.name AS class_name FROM students s JOIN classes c ON c.id=s.class_id '
            'WHERE c.school_year_id=?', (y['id'],)):
        by_key.setdefault((_norm_name(s['full_name']), s['class_name']), []).append(s)
    out, tot = [], {'rows': 0, 'matched': 0, 'ambiguous': 0, 'unmatched': 0}
    for row in block:
        cands = by_key.get((_norm_name(row['name']), row['class']), [])
        tot['rows'] += 1
        if len(cands) == 1:
            s = cands[0]
            out.append({'name': row['name'], 'class': row['class'], 'verdict': 'matched',
                        'student_id': s['id'], 'student_name': s['full_name'],
                        'already_charity': bool(s['is_charity'] if 'is_charity' in s.keys() else 0)})
            tot['matched'] += 1
        elif len(cands) > 1:
            out.append({'name': row['name'], 'class': row['class'], 'verdict': 'ambiguous',
                        'candidates': [{'id': s['id'], 'full_name': s['full_name'],
                                        'class_name': s['class_name']} for s in cands]})
            tot['ambiguous'] += 1
        else:
            out.append({'name': row['name'], 'class': row['class'], 'verdict': 'unmatched'})
            tot['unmatched'] += 1
    con.close()
    return {'ok': True, 'year': y['name'], 'block_rows': len(block), 'rows': out, 'summary': tot}

