# ---------------- Báo cơm + tài khoản quản lý (GĐ3 mở rộng 2026-10-26) ----------------
# Báo cơm cho bếp ghi rõ 3 con số: TỔNG số suất cơm, từng PHÒNG bao nhiêu suất,
# và số SUẤT CƠM GIÁO VIÊN. Suất GV do quản lý nhập theo ngày; nếu chưa nhập,
# báo cáo phải ghi rõ "CHƯA BAO GỒM cơm giáo viên". Số suất học sinh tính trực
# tiếp từ danh sách đang học trừ báo nghỉ có hiệu lực (không chờ chốt ngày).
# Tài khoản quản lý = tài khoản phụ huynh liên kết NHIỀU học sinh (mô hình sẵn
# có parent_students) + liên kết hàng loạt; báo cắt cơm cho các em như phụ
# huynh có nhiều con, qua đúng luồng /api/me/* sẵn có.

@app.get('/api/kitchen/report')
async def kitchen_report(req: Request, date: str = ''):
    u, e = need_role(req, 'admin', 'bgh', 'bantru', 'bep')
    if e: return e
    date_str = date or now().date().isoformat()
    try:
        datetime.strptime(date_str, '%Y-%m-%d')
    except (ValueError, TypeError):
        return err(400, 'bad_date', 'Ngày chưa hợp lệ (YYYY-MM-DD).')
    con = db()
    y = current_year(con)
    if not y:
        con.close(); return err(400, 'no_year', 'Chưa có năm học.')
    students = con.execute(
        "SELECT s.*, c.name AS class_name FROM students s JOIN classes c ON c.id=s.class_id "
        "WHERE c.school_year_id=? AND s.status='dang_hoc'", (y['id'],)).fetchall()
    ids = {s['id'] for s in students}
    absent = {r['student_id'] for r in con.execute(
        "SELECT student_id FROM meal_absences WHERE meal_date=? AND status IN ('dung_han','muon_da_duyet')",
        (date_str,))} & ids
    rooms, unassigned, total = {}, 0, 0
    for s in students:
        if s['id'] in absent:
            continue
        total += 1
        rid = s['room_id'] if 'room_id' in s.keys() else None
        if rid:
            rooms.setdefault(rid, {'room_id': rid, 'room_name': '', 'teacher_name': '', 'portions': 0})
            rooms[rid]['portions'] += 1
        else:
            unassigned += 1
    for rid, r in rooms.items():
        rm = con.execute('SELECT * FROM rooms WHERE id=?', (rid,)).fetchone()
        r['room_name'] = rm['name'] if rm else ''
        r['teacher_name'] = rm['teacher_name'] if rm else ''
    tm = con.execute('SELECT * FROM teacher_meals WHERE meal_date=?', (date_str,)).fetchone()
    teacher = tm['portions'] if tm else None
    closing = current_closing(con, date_str)
    con.close()
    return {'ok': True, 'date': date_str, 'registered': len(students), 'absent': len(absent),
            'total_portions': total,
            'rooms': sorted(rooms.values(), key=lambda r: r['room_name']),
            'unassigned_portions': unassigned,
            'teacher_portions': teacher, 'teacher_reported': teacher is not None,
            'note': None if teacher is not None else 'CHƯA BAO GỒM cơm giáo viên',
            'grand_total': total + (teacher or 0), 'closed': bool(closing)}

