@app.post('/api/admin/parents/bulk-confirm')
async def admin_parents_bulk_confirm(req: Request):
    u, e = need_role(req, 'admin')
    if e: return e
    body = await req.json()
    groups_in = body.get('groups') or []
    con = db()
    y = current_year(con)
    if not y:
        con.close(); return err(400, 'no_year', 'Chưa có năm học.')
    t = now().isoformat(timespec='seconds')
    created, linked_n, skipped = 0, 0, []
    export_rows = []
    for g in groups_in:
        phone = _norm_phone(g.get('phone'))
        sids = g.get('student_ids') or []
        action = g.get('action')
        if not phone or not sids or action not in ('create', 'link'):
            continue
        kids = []
        for sid in sids:
            s = con.execute('SELECT s.*, c.name AS class_name, c.school_year_id FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=?', (sid,)).fetchone()
            if not s or s['school_year_id'] != y['id'] or s['status'] != 'dang_hoc':
                skipped.append({'student_id': sid, 'reason': 'Học sinh không còn đang học trong năm hiện tại.'})
                continue
            if con.execute('SELECT 1 FROM parent_students WHERE student_id=?', (sid,)).fetchone():
                skipped.append({'student_id': sid, 'reason': 'Em đã được gắn tài khoản phụ huynh.'})
                continue
            kids.append(s)
        if not kids:
            continue
        if action == 'create':
            if con.execute('SELECT 1 FROM users WHERE username=?', (phone,)).fetchone():
                skipped.append({'phone': phone, 'reason': 'Tên đăng nhập đã tồn tại.'})
                continue
            temp = gen_temp_password()
            name = 'Phụ huynh ' + kids[0]['full_name']
            cur = con.execute('INSERT INTO users(username,full_name,phone,password_hash,must_change_pw,created_at) VALUES(?,?,?,?,1,?)',
                              (phone, name, phone, ph.hash(temp), t))
            pid = cur.lastrowid
            con.execute("INSERT INTO user_roles(user_id,role_code) VALUES(?,'phuhuynh')", (pid,))
            created += 1
            for s in kids:
                con.execute('INSERT OR IGNORE INTO parent_students(parent_user_id,student_id) VALUES(?,?)', (pid, s['id']))
                linked_n += 1
                export_rows.append([s['full_name'], s['class_name'], phone, name, temp, 'Mới tạo'])
        else:
            pid = g.get('account_id')
            ok = con.execute("SELECT 1 FROM user_roles WHERE user_id=? AND role_code='phuhuynh'", (pid,)).fetchone() if pid else None
            if not ok:
                skipped.append({'phone': phone, 'reason': 'Tài khoản gắn thêm không còn là tài khoản phụ huynh.'})
                continue
            acc = con.execute('SELECT * FROM users WHERE id=?', (pid,)).fetchone()
            for s in kids:
                con.execute('INSERT OR IGNORE INTO parent_students(parent_user_id,student_id) VALUES(?,?)', (pid, s['id']))
                linked_n += 1
                export_rows.append([s['full_name'], s['class_name'], acc['username'], acc['full_name'], '', 'Gắn thêm'])
    wb = openpyxl.Workbook()
    ws = wb.active; ws.title = 'Tài khoản phụ huynh'
    ws.append(['Họ tên học sinh', 'Lớp', 'Tên đăng nhập (SĐT)', 'Họ tên tài khoản', 'Mật khẩu tạm', 'Ghi chú'])
    for r in export_rows:
        ws.append(r)
    buf = io.BytesIO(); wb.save(buf)
    audit(con, 'user_create', 'ok', user=u,
          detail='Tạo hàng loạt TK phụ huynh: %d tài khoản mới, gắn %d em' % (created, linked_n),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'created_accounts': created, 'linked_students': linked_n,
            'skipped': skipped, 'export_filename': 'Tai_khoan_phu_huynh.xlsx',
            'export_b64': base64.b64encode(buf.getvalue()).decode()}

# ---------------- Thực đơn tuần (thiết kế lại 2026-10-26, thay ảnh mẫu) ----------------
# Trước đây màn hình Thực đơn chỉ là ảnh mẫu minh họa, không có chức năng thật.
# Nay: thực đơn theo tuần (khóa = thứ 2 đầu tuần), mỗi ngày Thứ 2–Thứ 6 gồm
# món chính, món rau/xào, canh, tráng miệng + ghi chú. Quản lý/nhà trường soạn,
# bếp và phụ huynh xem. Không giá tiền, không tính dinh dưỡng (đề án loại trừ).

def _monday_of(ds):
    try:
        d = datetime.strptime(ds, '%Y-%m-%d').date()
    except (ValueError, TypeError):
        return None
    return (d - timedelta(days=d.isoweekday() - 1)).isoformat()

def _menu_week_data(con, week_start):
    rows = {r['weekday']: r for r in con.execute(
        'SELECT * FROM menu_days WHERE week_start=?', (week_start,))}
    mon = datetime.strptime(week_start, '%Y-%m-%d').date()
    days = []
    for wd in range(1, 6):
        r = rows.get(wd)
        days.append({'weekday': wd, 'date': (mon + timedelta(days=wd - 1)).isoformat(),
                     'main_dish': r['main_dish'] if r else '',
                     'veg_dish': r['veg_dish'] if r else '',
                     'soup': r['soup'] if r else '',
                     'dessert': r['dessert'] if r else '',
                     'note': r['note'] if r else ''})
    return days

