def _clean_dish(v):
    return (v or '').strip()[:200]

@app.post('/api/menus/week')
async def menus_week_save(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    ws = _monday_of((body.get('week_start') or '').strip())
    days = body.get('days') or []
    if not ws or not isinstance(days, list):
        return err(400, 'bad_menu', 'Thiếu ngày đầu tuần hoặc danh sách ngày.')
    con = db()
    t = now().isoformat(timespec='seconds')
    for d in days:
        wd = d.get('weekday')
        if wd not in (1, 2, 3, 4, 5):
            con.close(); return err(400, 'bad_menu', 'Thứ trong tuần chỉ nhận 1–5 (Thứ 2–Thứ 6).')
        con.execute('INSERT INTO menu_days(week_start,weekday,main_dish,veg_dish,soup,dessert,note,updated_by,updated_at) '
                    'VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(week_start,weekday) DO UPDATE SET '
                    'main_dish=excluded.main_dish, veg_dish=excluded.veg_dish, soup=excluded.soup, '
                    'dessert=excluded.dessert, note=excluded.note, updated_by=excluded.updated_by, '
                    'updated_at=excluded.updated_at',
                    (ws, wd, _clean_dish(d.get('main_dish')), _clean_dish(d.get('veg_dish')),
                     _clean_dish(d.get('soup')), _clean_dish(d.get('dessert')), _clean_dish(d.get('note')),
                     u['id'], t))
    audit(con, 'menu', 'ok', user=u, detail='Lưu thực đơn tuần %s' % ws,
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'week_start': ws}

