# ---------------- Giai đoạn 3: Nhập Excel ----------------

IMPORT_COLS = ['Ho_ten_hoc_sinh', 'Khoi', 'Lop', 'SDT_phu_huynh', 'Ma_hoc_sinh']

def _xlsx_response(wb, filename):
    buf = io.BytesIO(); wb.save(buf)
    return Response(buf.getvalue(),
                    media_type='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                    headers={'Content-Disposition': 'attachment; filename="%s"' % filename})

@app.get('/api/import/template')
async def import_template(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    wb = openpyxl.Workbook()
    ws = wb.active; ws.title = 'Danh sach hoc sinh'
    ws.append(IMPORT_COLS)
    for c in ws[1]:
        c.font = Font(bold=True); c.fill = PatternFill('solid', fgColor='D9E2F3')
    ws.append(['Nguyễn Văn An', 2, '2A1', '0901234567', 'HS001'])
    for col, w in zip('ABCDE', (26, 8, 10, 16, 14)):
        ws.column_dimensions[col].width = w
    hd = wb.create_sheet('Huong dan')
    for line in [
        'HƯỚNG DẪN NHẬP DANH SÁCH HỌC SINH — BÁN TRÚ THÔNG MINH', '',
        '1. Ho_ten_hoc_sinh (bắt buộc): họ và tên đầy đủ của học sinh.',
        '2. Khoi (bắt buộc): khối lớp, số từ 1 đến 5 — phải khớp với lớp.',
        '3. Lop (bắt buộc): tên lớp phải đã có trong hệ thống (vd: 2A1).',
        '4. SDT_phu_huynh: số điện thoại 10 chữ số bắt đầu bằng 0. Cột này phải để định dạng Text để giữ số 0 ở đầu.',
        '5. Ma_hoc_sinh: mã học sinh (nên có) — dùng làm khóa đối chiếu chống trùng.',
        '6. Dòng đầu tiên là tiêu đề cột, không sửa tên các cột. Dòng 2 trong tệp là ví dụ, hãy xóa trước khi nhập số liệu thật.',
        '7. Quy trình: tải tệp lên → hệ thống xem trước và báo dòng hợp lệ/lỗi/trùng → chỉ khi bấm "Xác nhận nhập" dữ liệu mới vào hệ thống.',
    ]:
        hd.append([line])
    hd.column_dimensions['A'].width = 130
    return _xlsx_response(wb, 'mau-nhap-hoc-sinh.xlsx')

def _cell_text(v):
    if v is None: return ''
    if isinstance(v, float) and v == int(v): return str(int(v))
    return str(v).strip()

def _validate_import(con, raw_rows):
    """Kiểm tra từng dòng theo Mục 9: bắt buộc, khối 1–5, lớp tồn tại & khớp khối,
    SĐT đúng định dạng, trùng trong tệp và trùng với dữ liệu đã có."""
    y = current_year(con)
    classes = {}
    if y:
        classes = {r['name']: r for r in con.execute('SELECT * FROM classes WHERE school_year_id=?', (y['id'],))}
    by_code, by_key = {}, {}
    for s in con.execute('SELECT s.*, c.name AS cname FROM students s JOIN classes c ON c.id=s.class_id'):
        if s['code']: by_code[s['code']] = s
        by_key[(s['full_name'].lower(), s['cname'], s['parent_phone'] or '')] = s
    seen_code, seen_key = {}, {}
    out = []
    for i, r in enumerate(raw_rows):
        name = _cell_text(r.get('Ho_ten_hoc_sinh'))
        khoi_raw = _cell_text(r.get('Khoi'))
        lop = _cell_text(r.get('Lop')).upper()
        phone = _cell_text(r.get('SDT_phu_huynh'))
        code = _cell_text(r.get('Ma_hoc_sinh'))
        reasons = []
        khoi = None
        if not name: reasons.append('Thiếu họ tên học sinh')
        try:
            khoi = int(khoi_raw)
            if not (1 <= khoi <= 5): reasons.append('Khối phải từ 1 đến 5')
        except (TypeError, ValueError):
            reasons.append('Khối chưa hợp lệ')
        cls = classes.get(lop)
        if not lop: reasons.append('Thiếu tên lớp')
        elif not cls: reasons.append('Lớp %s chưa có trong hệ thống' % lop)
        elif khoi is not None and cls['grade'] != khoi:
            reasons.append('Khối %s không khớp với lớp %s (khối %d)' % (khoi_raw, lop, cls['grade']))
        if phone and not re.fullmatch(r'0\d{9}', phone):
            reasons.append('SĐT phụ huynh phải gồm 10 chữ số bắt đầu bằng 0 (kiểm tra định dạng Text để giữ số 0 đầu)')
        verdict, dup_of = 'ok', None
        if not reasons:
            key = (name.lower(), lop, phone)
            # Trùng NGAY TRONG TỆP xét trước: dòng lặp lại trong cùng tệp luôn bị bỏ qua,
            # dòng đầu tiên trong tệp là dòng có hiệu lực (tránh hai dòng cùng tệp ghi đè nhau).
            if code and code in seen_code: verdict, dup_of = 'dup', 'file:%d' % seen_code[code]
            elif key in seen_key: verdict, dup_of = 'dup', 'file:%d' % seen_key[key]
            elif code and code in by_code: verdict, dup_of = 'dup', by_code[code]['id']
            elif key in by_key: verdict, dup_of = 'dup', by_key[key]['id']
            if code: seen_code.setdefault(code, i)
            seen_key.setdefault(key, i)
        out.append({'row': i + 2, 'name': name, 'khoi': khoi, 'lop': lop, 'phone': phone,
                    'code': code, 'verdict': 'error' if reasons else verdict,
                    'reasons': reasons, 'dup_of': dup_of,
                    'class_id': cls['id'] if cls and not reasons else (cls['id'] if cls else None)})
    return out

@app.post('/api/import/preview')
async def import_preview(req: Request, file: UploadFile = File(...)):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    data = await file.read()
    try:
        wb = openpyxl.load_workbook(io.BytesIO(data), read_only=True, data_only=True)
        ws = wb.active
        rows_iter = ws.iter_rows(values_only=True)
        header = [(_cell_text(c) if c is not None else '') for c in next(rows_iter)]
        idx = {name: (header.index(name) if name in header else -1) for name in IMPORT_COLS}
        if idx['Ho_ten_hoc_sinh'] < 0 or idx['Lop'] < 0:
            return err(400, 'bad_template', 'Tệp thiếu cột bắt buộc Ho_ten_hoc_sinh / Lop. Hãy dùng đúng tệp mẫu.')
        raw = []
        for row in rows_iter:
            if row is None or all(c is None or _cell_text(c) == '' for c in row): continue
            raw.append({name: (row[i] if i >= 0 and i < len(row) else None) for name, i in idx.items()})
    except Exception:
        return err(400, 'bad_file', 'Không đọc được tệp Excel. Hãy kiểm tra lại định dạng .xlsx.')
    con = db()
    checked = _validate_import(con, raw)
    counts = {'total': len(checked),
              'valid': sum(1 for r in checked if r['verdict'] == 'ok'),
              'error': sum(1 for r in checked if r['verdict'] == 'error'),
              'dup': sum(1 for r in checked if r['verdict'] == 'dup')}
    cur = con.execute(
        'INSERT INTO import_jobs(ts,user_id,username,filename,status,total_rows,valid_rows,error_rows,dup_rows,rows_json) '
        'VALUES(?,?,?,?,?,?,?,?,?,?)',
        (now().isoformat(timespec='seconds'), u['id'], u['username'], file.filename, 'preview',
         counts['total'], counts['valid'], counts['error'], counts['dup'], json.dumps(checked, ensure_ascii=False)))
    audit(con, 'import_preview', 'ok', user=u,
          detail='Xem trước nhập %s: %d dòng (hợp lệ %d, lỗi %d, trùng %d)' % (file.filename, counts['total'], counts['valid'], counts['error'], counts['dup']),
          ip=req.client.host if req.client else '')
    con.commit(); job_id = cur.lastrowid; con.close()
    return {'ok': True, 'job_id': job_id, 'counts': counts, 'rows': checked}

