# ---------------- Giai đoạn 4: Lịch bán trú & báo nghỉ ----------------

ABSENCE_LABELS = {'dung_han': 'Đúng hạn', 'muon_cho_duyet': 'Quá hạn — chờ duyệt',
                  'muon_da_duyet': 'Quá hạn — đã duyệt', 'muon_tu_choi': 'Quá hạn — bị từ chối',
                  'da_huy': 'Đã hủy'}
ACTIVE_ABSENCE = ('dung_han', 'muon_cho_duyet', 'muon_da_duyet')

def cutoff_for(con, d):
    if d.isoweekday() == 3:
        w = (setting(con, 'cutoff_wed', '') or '').strip()
        if w: return w
    return (setting(con, 'cutoff_default', '08:00') or '08:00').strip()

def meal_day_info(con, d):
    """Thông tin ngày ăn: có phục vụ không, hạn báo nghỉ, ghi chú (lịch riêng theo ngày ưu tiên)."""
    cal = con.execute('SELECT * FROM meal_calendar WHERE date=?', (d.isoformat(),)).fetchone()
    if cal:
        return {'date': d.isoformat(), 'serve': bool(cal['serve']),
                'cutoff': (cal['cutoff_time'] or cutoff_for(con, d)) if cal['serve'] else None,
                'note': cal['note'] or ''}
    days = {int(x) for x in (setting(con, 'serve_weekdays', '1,2,4,5') or '1,2,4,5').split(',') if x.strip()}
    serve = d.isoweekday() in days
    return {'date': d.isoformat(), 'serve': serve, 'cutoff': cutoff_for(con, d) if serve else None, 'note': ''}

def absence_status_for(con, meal_date):
    """Trạng thái khi gửi lúc này, tính theo giờ máy chủ: ngày mai trở đi = đúng hạn;
    hôm nay: trước giờ hạn = đúng hạn, từ giờ hạn = quá hạn chờ duyệt."""
    t = now()
    today = t.date()
    if meal_date > today:
        return 'dung_han'
    hh, mm = meal_day_info(con, meal_date)['cutoff'].split(':')
    cutoff_dt = datetime(meal_date.year, meal_date.month, meal_date.day, int(hh), int(mm), tzinfo=TZ)
    return 'dung_han' if t < cutoff_dt else 'muon_cho_duyet'

def absence_pub(con, a):
    s = con.execute('SELECT s.*, c.name AS cname FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=?',
                    (a['student_id'],)).fetchone()
    return {'id': a['id'], 'code': 'BN-%04d' % a['id'], 'student_id': a['student_id'],
            'student_name': s['full_name'] if s else '', 'class_name': s['cname'] if s else '',
            'meal_date': a['meal_date'], 'reason': a['reason'], 'status': a['status'],
            'status_label': ABSENCE_LABELS.get(a['status'], a['status']),
            'submitted_at': a['submitted_at'], 'decision_note': a['decision_note']}

def my_children(con, user_id):
    return con.execute(
        'SELECT s.*, c.name AS cname, c.grade FROM parent_students ps '
        'JOIN students s ON s.id = ps.student_id JOIN classes c ON c.id = s.class_id '
        'WHERE ps.parent_user_id=? ORDER BY c.grade, c.name, s.full_name', (user_id,)).fetchall()

@app.get('/api/me/children')
async def me_children(req: Request):
    u, e = need_role(req, 'phuhuynh')
    if e: return e
    con = db()
    out = [{'id': s['id'], 'code': s['code'], 'full_name': s['full_name'],
            'class_name': s['cname'], 'grade': s['grade'], 'status': s['status']} for s in my_children(con, u['id'])]
    con.close()
    return {'ok': True, 'children': out, 'server_now': now().isoformat(timespec='seconds')}

@app.get('/api/me/calendar')
async def me_calendar(req: Request, days: int = 7):
    u, e = need_role(req, 'phuhuynh')
    if e: return e
    days = max(1, min(days, 14))
    con = db()
    kids = my_children(con, u['id'])
    today = now().date()
    out = []
    for s in kids:
        entries = []
        for i in range(days):
            d = today + timedelta(days=i)
            info = meal_day_info(con, d)
            a = con.execute('SELECT * FROM meal_absences WHERE student_id=? AND meal_date=? AND status IN (?,?,?)',
                            (s['id'], d.isoformat(), *ACTIVE_ABSENCE)).fetchone() \
                if info['serve'] else None
            entries.append({'date': info['date'], 'weekday': d.isoweekday(), 'serve': info['serve'],
                            'cutoff': info['cutoff'], 'note': info['note'],
                            'absence': absence_pub(con, a) if a else None})
        out.append({'student': {'id': s['id'], 'full_name': s['full_name'], 'class_name': s['cname']},
                    'days': entries})
    con.close()
    return {'ok': True, 'calendar': out, 'server_now': now().isoformat(timespec='seconds')}

@app.post('/api/me/absences')
async def me_submit_absence(req: Request):
    u, e = need_role(req, 'phuhuynh')
    if e: return e
    body = await req.json()
    student_id = body.get('student_id')
    date_str = (body.get('meal_date') or '').strip()
    reason = (body.get('reason') or '').strip()
    try:
        meal_date = datetime.strptime(date_str, '%Y-%m-%d').date()
    except (ValueError, TypeError):
        return err(400, 'bad_date', 'Ngày ăn chưa hợp lệ.')
    con = db()
    kid_ids = {s['id'] for s in my_children(con, u['id'])}
    if student_id not in kid_ids:
        con.close(); return err(403, 'not_your_child', 'Học sinh này không thuộc tài khoản của anh/chị.')
    s = con.execute('SELECT * FROM students WHERE id=?', (student_id,)).fetchone()
    if not s or s['status'] != 'dang_hoc':
        con.close(); return err(400, 'student_inactive', 'Học sinh hiện không ở trạng thái đang học.')
    if meal_date < now().date():
        con.close(); return err(400, 'past_date', 'Không báo nghỉ được cho ngày đã qua.')
    info = meal_day_info(con, meal_date)
    if not info['serve']:
        con.close(); return err(400, 'no_service', 'Ngày này trường không phục vụ bán trú.')
    if current_closing(con, meal_date.isoformat()):
        con.close(); return err(400, 'day_closed', 'Ngày ăn này đã chốt suất. Vui lòng liên hệ nhà trường để được hỗ trợ.')
    dup = con.execute('SELECT 1 FROM meal_absences WHERE student_id=? AND meal_date=? AND status IN (?,?,?)',
                      (student_id, meal_date.isoformat(), *ACTIVE_ABSENCE)).fetchone()
    if dup:
        con.close(); return err(409, 'duplicate', 'Học sinh đã có báo nghỉ cho ngày này rồi.')
    status = absence_status_for(con, meal_date)
    try:
        cur = con.execute('INSERT INTO meal_absences(student_id,meal_date,reason,status,submitted_at,submitted_by) '
                          'VALUES(?,?,?,?,?,?)',
                          (student_id, meal_date.isoformat(), reason or None, status,
                           now().isoformat(timespec='seconds'), u['id']))
    except sqlite3.IntegrityError:
        con.close(); return err(409, 'duplicate', 'Học sinh đã có báo nghỉ cho ngày này rồi.')
    a = con.execute('SELECT * FROM meal_absences WHERE id=?', (cur.lastrowid,)).fetchone()
    if status == 'muon_cho_duyet':
        for role_code in ('bantru', 'admin'):
            notify_role(con, role_code, 'late_submitted', 'Có báo nghỉ quá hạn chờ duyệt',
                        '%s (%s) báo nghỉ ngày %s — đang chờ duyệt.' % (s['full_name'],
                        con.execute('SELECT name FROM classes WHERE id=?', (s['class_id'],)).fetchone()['name'],
                        meal_date.isoformat()), ref_id=a['id'])
    audit(con, 'absence_submit', 'ok', user=u,
          detail='Báo nghỉ %s cho %s ngày %s (%s)' % (a['id'], s['full_name'], meal_date.isoformat(), status),
          ip=req.client.host if req.client else '')
    con.commit()
    out = absence_pub(con, a)
    con.close()
    return {'ok': True, 'absence': out}

@app.post('/api/me/absences/{aid}/cancel')
async def me_cancel_absence(req: Request, aid: int):
    u, e = need_role(req, 'phuhuynh')
    if e: return e
    con = db()
    a = con.execute('SELECT * FROM meal_absences WHERE id=?', (aid,)).fetchone()
    kid_ids = {s['id'] for s in my_children(con, u['id'])}
    if not a or a['student_id'] not in kid_ids:
        con.close(); return err(404, 'not_found', 'Không tìm thấy báo nghỉ.')
    if current_closing(con, a['meal_date']):
        con.close(); return err(400, 'day_closed', 'Ngày ăn này đã chốt suất, không thay đổi được nữa. Vui lòng liên hệ nhà trường.')
    if a['status'] not in ('dung_han', 'muon_cho_duyet'):
        con.close(); return err(400, 'cannot_cancel', 'Báo nghỉ này không còn hủy được.')
    meal_date = datetime.strptime(a['meal_date'], '%Y-%m-%d').date()
    if a['status'] == 'dung_han' and meal_date == now().date():
        info = meal_day_info(con, meal_date)
        hh, mm = info['cutoff'].split(':')
        cutoff_dt = datetime(meal_date.year, meal_date.month, meal_date.day, int(hh), int(mm), tzinfo=TZ)
        if now() >= cutoff_dt:
            con.close()
            return err(400, 'past_cutoff', 'Đã qua giờ hạn báo nghỉ, không tự hủy được nữa. Vui lòng liên hệ nhà trường.')
    con.execute("UPDATE meal_absences SET status='da_huy', cancelled_at=? WHERE id=?",
                (now().isoformat(timespec='seconds'), aid))
    audit(con, 'absence_cancel', 'ok', user=u, detail='Hủy báo nghỉ #%d (%s)' % (aid, a['meal_date']),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True}

@app.get('/api/me/absences')
async def me_absences(req: Request):
    u, e = need_role(req, 'phuhuynh')
