# ---------------- Giai đoạn 5: Quản trị bán trú ----------------

def current_closing(con, date_str):
    return con.execute("SELECT * FROM meal_closings WHERE meal_date=? AND status='closed' "
                       'ORDER BY version DESC LIMIT 1', (date_str,)).fetchone()

def day_stats(con, d, scope_names=None):
    """Số liệu một ngày ăn, tính từ dữ liệu gốc: suất = đăng ký − báo nghỉ có hiệu lực
    (đúng hạn + muộn đã duyệt). Báo muộn chờ duyệt KHÔNG trừ. scope_names: giới hạn theo lớp (GVCN)."""
    date_str = d.isoformat()
    info = meal_day_info(con, d)
    classes = con.execute(
        'SELECT c.* FROM classes c JOIN school_years y ON y.id=c.school_year_id '
        'WHERE y.id=(SELECT id FROM school_years WHERE is_current=1) ORDER BY c.grade, c.name').fetchall()
    per_class = []
    tot = {'registered': 0, 'on_time': 0, 'late_pending': 0, 'late_approved': 0,
           'late_rejected': 0, 'cancelled': 0, 'effective': 0, 'meals': 0}
    for c in classes:
        if scope_names is not None and c['name'] not in scope_names:
            continue
        reg = con.execute("SELECT COUNT(*) n FROM students WHERE class_id=? AND status='dang_hoc'", (c['id'],)).fetchone()['n']
        counts = {r['status']: r['n'] for r in con.execute(
            'SELECT a.status, COUNT(*) n FROM meal_absences a JOIN students s ON s.id=a.student_id '
            'WHERE a.meal_date=? AND s.class_id=? GROUP BY a.status', (date_str, c['id']))}
        eff = counts.get('dung_han', 0) + counts.get('muon_da_duyet', 0)
        row = {'class_id': c['id'], 'class_name': c['name'], 'grade': c['grade'], 'registered': reg,
               'on_time': counts.get('dung_han', 0), 'late_pending': counts.get('muon_cho_duyet', 0),
               'late_approved': counts.get('muon_da_duyet', 0), 'late_rejected': counts.get('muon_tu_choi', 0),
               'cancelled': counts.get('da_huy', 0), 'effective_absences': eff, 'meals': reg - eff}
        per_class.append(row)
        for k in ('registered', 'on_time', 'late_pending', 'late_approved', 'late_rejected', 'cancelled'):
            tot[k] += row[k]
        tot['effective'] += eff; tot['meals'] += row['meals']
    closing = current_closing(con, date_str)
    return {'date': date_str, 'serve': info['serve'], 'cutoff': info['cutoff'], 'note': info['note'],
            'totals': tot, 'per_class': per_class,
            'closing': ({'version': closing['version'], 'total_meals': closing['total_meals'],
                          'closed_by': closing['closed_by'], 'closed_at': closing['closed_at']} if closing else None)}

def staff_scope(con, u):
    roles = {r['code'] for r in roles_of(con, u['id'])}
    if roles & {'admin', 'bantru', 'bgh'}:
        return roles, None
    return roles, gvcn_class_names(con, u['id'])

@app.get('/api/staff/day')
async def staff_day(req: Request, date: str = ''):
    u, e = need_role(req, 'admin', 'bantru', 'bgh', 'gvcn')
    if e: return e
    try:
        d = datetime.strptime(date, '%Y-%m-%d').date() if date else now().date()
    except ValueError:
        return err(400, 'bad_date', 'Ngày chưa hợp lệ.')
    con = db()
    roles, scope = staff_scope(con, u)
    st = day_stats(con, d, scope)
    if st['closing']:
        row = con.execute('SELECT full_name FROM users WHERE id=?', (st['closing']['closed_by'],)).fetchone()
        st['closing']['closed_by_name'] = row['full_name'] if row else ''
    st['can_manage'] = bool(roles & {'admin', 'bantru'})
    con.close()
    return {'ok': True, **st}

@app.get('/api/staff/absences')
async def staff_absences(req: Request, date: str = '', status: str = ''):
    u, e = need_role(req, 'admin', 'bantru', 'bgh', 'gvcn')
    if e: return e
    date_str = date or now().date().isoformat()
    con = db()
    roles, scope = staff_scope(con, u)
    sql = ('SELECT a.*, s.full_name AS sname, c.name AS cname, pu.full_name AS pname, pu.phone AS pphone '
           'FROM meal_absences a JOIN students s ON s.id=a.student_id JOIN classes c ON c.id=s.class_id '
           'JOIN users pu ON pu.id=a.submitted_by WHERE a.meal_date=?')
    args = [date_str]
    if status:
        sql += ' AND a.status=?'; args.append(status)
    if scope is not None:
        if not scope:
            con.close(); return {'ok': True, 'absences': []}
        sql += ' AND c.name IN (%s)' % ','.join('?' * len(scope)); args += scope
    sql += ' ORDER BY a.id DESC'
    rows = con.execute(sql, args).fetchall()
    out = []
    for a in rows:
        item = absence_pub(con, a)
        item['parent_name'] = a['pname']; item['parent_phone'] = a['pphone']
        item['submitted_by'] = a['submitted_by']
        out.append(item)
    con.close()
    return {'ok': True, 'absences': out}

@app.post('/api/staff/absences/{aid}/decide')
async def staff_decide(req: Request, aid: int):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    decision = body.get('decision')
    if decision not in ('approve', 'reject'):
        return err(400, 'bad_decision', 'Quyết định phải là duyệt hoặc từ chối.')
    con = db()
    a = con.execute('SELECT * FROM meal_absences WHERE id=?', (aid,)).fetchone()
    if not a:
        con.close(); return err(404, 'not_found', 'Không tìm thấy báo nghỉ.')
    if a['status'] != 'muon_cho_duyet':
        con.close(); return err(400, 'not_pending', 'Báo nghỉ này không ở trạng thái chờ duyệt.')
    if current_closing(con, a['meal_date']):
        con.close(); return err(400, 'day_closed', 'Ngày ăn đã chốt suất, không duyệt thêm được.')
    new_status = 'muon_da_duyet' if decision == 'approve' else 'muon_tu_choi'
    note = (body.get('note') or '').strip() or None
    con.execute('UPDATE meal_absences SET status=?, decided_by=?, decided_at=?, decision_note=? WHERE id=?',
                (new_status, u['id'], now().isoformat(timespec='seconds'), note, aid))
    srow = con.execute('SELECT full_name FROM students WHERE id=?', (a['student_id'],)).fetchone()
    notify(con, a['submitted_by'], 'absence_decided',
           ('Báo nghỉ quá hạn đã được DUYỆT' if decision == 'approve' else 'Báo nghỉ quá hạn bị TỪ CHỐI'),
           'Báo nghỉ %s của %s cho ngày %s: %s.%s' % ('BN-%04d' % aid, srow['full_name'] if srow else '',
           a['meal_date'], 'đã được duyệt' if decision == 'approve' else 'bị từ chối',
           (' Ghi chú: ' + note) if note else ''), ref_id=aid)
    audit(con, 'absence_decide', 'ok', user=u,
          detail='%s báo nghỉ #%d (%s)' % ('Duyệt' if decision == 'approve' else 'Từ chối', aid, a['meal_date']),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'status': new_status}

@app.post('/api/staff/close')
async def staff_close(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    date_str = (body.get('date') or '').strip() or now().date().isoformat()
    try:
        d = datetime.strptime(date_str, '%Y-%m-%d').date()
    except ValueError:
        return err(400, 'bad_date', 'Ngày chưa hợp lệ.')
    con = db()
    if not meal_day_info(con, d)['serve']:
        con.close(); return err(400, 'no_service', 'Ngày này không phục vụ bán trú, không cần chốt.')
    if current_closing(con, date_str):
        con.close(); return err(409, 'already_closed', 'Ngày này đã chốt rồi. Muốn chốt lại phải mở chốt trước.')
    st = day_stats(con, d)
    ver = (con.execute('SELECT MAX(version) v FROM meal_closings WHERE meal_date=?', (date_str,)).fetchone()['v'] or 0) + 1
    snapshot = {'totals': st['totals'], 'per_class': st['per_class']}
    con.execute('INSERT INTO meal_closings(meal_date,version,closed_by,closed_at,total_meals,snapshot_json) '
                'VALUES(?,?,?,?,?,?)',
                (date_str, ver, u['id'], now().isoformat(timespec='seconds'),
                 st['totals']['meals'], json.dumps(snapshot, ensure_ascii=False)))
    notify_role(con, 'bep', 'meal_closed', 'Đã chốt suất ăn ngày %s' % date_str,
                'Tổng %d suất (phiên bản %d). Vào mục Nhà bếp để xem chi tiết theo lớp.' % (st['totals']['meals'], ver))
    audit(con, 'meal_close', 'ok', user=u,
          detail='Chốt suất %s phiên bản %d: %d suất' % (date_str, ver, st['totals']['meals']),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'version': ver, 'total_meals': st['totals']['meals']}

@app.post('/api/staff/reopen')
async def staff_reopen(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    date_str = (body.get('date') or '').strip()
    reason = (body.get('reason') or '').strip()
    if not reason:
        return err(400, 'need_reason', 'Mở chốt bắt buộc phải nhập lý do.')
    con = db()
    closing = current_closing(con, date_str)
    if not closing:
        con.close(); return err(400, 'not_closed', 'Ngày này chưa chốt nên không mở chốt được.')
    con.execute("UPDATE meal_closings SET status='reopened', reopen_reason=?, reopened_by=?, reopened_at=? WHERE id=?",
                (reason, u['id'], now().isoformat(timespec='seconds'), closing['id']))
    notify_role(con, 'bep', 'meal_reopened', 'Đã mở chốt suất ngày %s' % date_str,
                'Số suất đang được xử lý lại. Nhà bếp chờ bản chốt mới trước khi nấu theo số mới.')
    audit(con, 'meal_reopen', 'ok', user=u,
          detail='Mở chốt %s (bản v%d). Lý do: %s' % (date_str, closing['version'], reason),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True}

@app.get('/api/kitchen/day')
async def kitchen_day(req: Request, date: str = ''):
    u, e = need_role(req, 'bep', 'admin', 'bantru')
    if e: return e
    date_str = date or now().date().isoformat()
    con = db()
    closing = current_closing(con, date_str)
    if not closing:
        con.close()
        return {'ok': True, 'date': date_str, 'closed': False,
                'message': 'Ngày này chưa chốt suất. Nhà bếp chỉ xem được số suất sau khi đã chốt.'}
    snap = json.loads(closing['snapshot_json'])
    out = {'ok': True, 'date': date_str, 'closed': True, 'version': closing['version'],
           'total_meals': closing['total_meals'], 'closed_at': closing['closed_at'],
           'per_class': [{'class_name': r['class_name'], 'meals': r['meals']} for r in snap['per_class']]}
    con.close()
    return out

# ---------------- Giai đoạn 6: Thông báo, báo cáo, sao lưu ----------------

def notify(con, user_id, kind, title, body, ref_id=None):
    con.execute('INSERT INTO notifications(user_id,ts,kind,title,body,ref_id) VALUES(?,?,?,?,?,?)',
                (user_id, now().isoformat(timespec='seconds'), kind, title, body, ref_id))

