# ---------------- Tạo thông báo thủ công (thầy dặn 26/10) ----------------
# Chỉ tài khoản quản lý bán trú (role bantru) và quản trị viên (admin) được
# gửi. Người gửi không tự nhận thông báo của mình. Tài khoản bị khóa không
# nhận. Đối tượng: all = toàn trường, parents = chỉ phụ huynh,
# staff = chỉ cán bộ – nhân viên (admin, bgh, gvcn, bantru, bep).
@app.post('/api/notifications')
async def notifications_create(req: Request):
    u, e = need_role(req, 'admin', 'bantru')
    if e: return e
    body = await req.json()
    title = (body.get('title') or '').strip()
    text = (body.get('body') or '').strip()
    audience = body.get('audience') or 'all'
    if not title or len(title) > 200:
        return err(400, 'bad_title', 'Tiêu đề bắt buộc, tối đa 200 ký tự.')
    if not text or len(text) > 2000:
        return err(400, 'bad_body', 'Nội dung bắt buộc, tối đa 2000 ký tự.')
    if audience not in ('all', 'parents', 'staff'):
        return err(400, 'bad_audience', 'Đối tượng nhận chưa hợp lệ.')
    con = db()
    if audience == 'all':
        rows = con.execute("SELECT id FROM users WHERE status='active' AND id<>?", (u['id'],)).fetchall()
    elif audience == 'parents':
        rows = con.execute("SELECT DISTINCT u.id FROM users u JOIN user_roles r ON r.user_id=u.id "
                           "WHERE u.status='active' AND u.id<>? AND r.role_code='phuhuynh'", (u['id'],)).fetchall()
    else:
        rows = con.execute("SELECT DISTINCT u.id FROM users u JOIN user_roles r ON r.user_id=u.id "
                           "WHERE u.status='active' AND u.id<>? AND r.role_code IN ('admin','bgh','gvcn','bantru','bep')",
                           (u['id'],)).fetchall()
    for r in rows:
        notify(con, r['id'], 'manual', title, text)
    audit(con, 'notify', 'ok', user=u,
          detail='Gửi thông báo "%s" tới %s (%d người)' % (title, audience, len(rows)),
          ip=req.client.host if req.client else '')
    con.commit(); con.close()
    threading.Thread(target=_push_broadcast, args=(title, text, [r['id'] for r in rows]), daemon=True).start()
    return {'ok': True, 'sent': len(rows), 'audience': audience}

# ---------------- Thông báo đẩy kiểu tin nhắn (thầy dặn 26/10) ----------------
# Phụ huynh bấm "Bật thông báo" trên bản di động → trình duyệt đăng ký push
# (cần quyền hiển thị thông báo; trên iPhone cần "Thêm vào Màn hình chính"
# trước, iOS 16.4+). Khi nhà trường gửi thông báo thủ công, máy chủ push tới
# các subscription của người nhận: điện thoại hiện bảng tin kèm chuông hệ
# thống như khi có tin nhắn, kể cả khi không mở trang. Khóa VAPID tự sinh lần
# đầu và lưu trong bảng settings (bền vững theo CSDL, không cần thầy nhập).
# Chuông là chuông hệ thống của điện thoại (web push không cho chọn nhạc
# chuông riêng). Chỉ gửi cho thông báo thủ công; thông báo tự động của hệ
# thống (duyệt/từ chối, chốt suất) vẫn chỉ hiện trong ứng dụng.
# VAPID "sub" bắt buộc dạng mailto: (py-vapid kiểm tra tiền tố). Đây chỉ là
# địa chỉ liên hệ kỹ thuật để dịch vụ push báo cáo lạm dụng nếu có — không
# phải hộp thư thật, không gửi/nhận thư qua địa chỉ này.
PUSH_SUB = 'mailto:bantru@bao-bai-giao-an.onrender.com'

def _vapid_keys(con):
    """Trả về khóa VAPID; tự sinh lần đầu và lưu trong bảng settings.
    pywebpush cần private key dạng DER base64url (không phải PEM)."""
    from cryptography.hazmat.primitives.asymmetric import ec
    from cryptography.hazmat.primitives import serialization
    pub = setting(con, 'vapid_public', '')
    priv = setting(con, 'vapid_private', '')
    if pub and priv and not priv.startswith('-----'):
        return {'public': pub, 'private': priv}
    if pub and priv.startswith('-----'):
        # Hàng PEM cũ (chỉ có ở bản thử): chuyển sang DER base64url.
        key = serialization.load_pem_private_key(priv.encode(), None)
        priv = base64.urlsafe_b64encode(key.private_bytes(serialization.Encoding.DER, serialization.PrivateFormat.PKCS8, serialization.NoEncryption())).rstrip(b'=').decode()
        con.execute("INSERT INTO settings(key,value) VALUES('vapid_private',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (priv,))
        con.execute("DELETE FROM settings WHERE key='vapid_private_pem'")
        con.commit()
        return {'public': pub, 'private': priv}
    key = ec.generate_private_key(ec.SECP256R1())
    pub_raw = key.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    pub = base64.urlsafe_b64encode(pub_raw).rstrip(b'=').decode()
    priv = base64.urlsafe_b64encode(key.private_bytes(serialization.Encoding.DER, serialization.PrivateFormat.PKCS8, serialization.NoEncryption())).rstrip(b'=').decode()
    con.execute("INSERT INTO settings(key,value) VALUES('vapid_public',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (pub,))
    con.execute("INSERT INTO settings(key,value) VALUES('vapid_private',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (priv,))
    con.commit()
    return {'public': pub, 'private': priv}

