@app.post('/api/push/subscribe')
async def push_subscribe(req: Request):
    u, e = need_user(req)
    if e: return e
    body = await req.json()
    endpoint = (body.get('endpoint') or '').strip()
    keys = body.get('keys') or {}
    p256dh = (keys.get('p256dh') or '').strip()
    auth = (keys.get('auth') or '').strip()
    if not endpoint.startswith('https://') or not p256dh or not auth or len(endpoint) > 500 or len(p256dh) > 200 or len(auth) > 200:
        return err(400, 'bad_sub', 'Thông tin đăng ký push chưa hợp lệ.')
    con = db()
    con.execute('INSERT INTO push_subscriptions(user_id,endpoint,p256dh,auth,created_at) VALUES(?,?,?,?,?) '
                'ON CONFLICT(user_id,endpoint) DO UPDATE SET p256dh=excluded.p256dh, auth=excluded.auth, created_at=excluded.created_at',
                (u['id'], endpoint, p256dh, auth, now().isoformat(timespec='seconds')))
    con.commit(); con.close()
    return {'ok': True}

@app.post('/api/push/unsubscribe')
async def push_unsubscribe(req: Request):
    u, e = need_user(req)
    if e: return e
    body = await req.json()
    endpoint = (body.get('endpoint') or '').strip()
    con = db()
    con.execute('DELETE FROM push_subscriptions WHERE user_id=? AND endpoint=?', (u['id'], endpoint))
    con.commit(); con.close()
    return {'ok': True}

def _push_broadcast(title, body, user_ids):
    """Gửi push tới mọi subscription của các user_id (chạy nền, không chặn API)."""
    if not user_ids:
        return
    try:
        from pywebpush import webpush, WebPushException
        con = db()
        subs = con.execute('SELECT endpoint, p256dh, auth FROM push_subscriptions WHERE user_id IN (%s)' % ','.join('?' * len(user_ids)), user_ids).fetchall()
        vk = _vapid_keys(con)
        con.close()
    except Exception:
        return
    payload = json.dumps({'title': title, 'body': body}, ensure_ascii=False)
    for s in subs:
        try:
            webpush({'endpoint': s['endpoint'], 'keys': {'p256dh': s['p256dh'], 'auth': s['auth']}},
                    payload, vapid_private_key=vk['private'], vapid_claims={'sub': PUSH_SUB})
        except WebPushException as e:
            if e.response is not None and e.response.status_code in (404, 410):
                try:
                    con = db()
                    con.execute('DELETE FROM push_subscriptions WHERE endpoint=?', (s['endpoint'],))
                    con.commit(); con.close()
                except Exception:
                    pass
        except Exception:
            pass

