def _make_pdf(filename, title_lines, table_headers, table_rows, footer_lines):
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import cm
    from reportlab.lib import colors
    from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
    from reportlab.lib.styles import ParagraphStyle
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont
    try:
        pdfmetrics.registerFont(TTFont('DV', '/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf'))
        pdfmetrics.registerFont(TTFont('DV-B', '/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf'))
    except Exception:
        pass
    buf = io.BytesIO()
    doc = SimpleDocTemplate(buf, pagesize=A4, topMargin=1.6 * cm, bottomMargin=1.6 * cm,
                            leftMargin=1.8 * cm, rightMargin=1.8 * cm, title=title_lines[0])
    h1 = ParagraphStyle('h1', fontName='DV-B', fontSize=15, leading=20, alignment=1, textColor=colors.HexColor('#1e40af'))
    h2 = ParagraphStyle('h2', fontName='DV', fontSize=11, leading=15, alignment=1)
    cell = ParagraphStyle('cell', fontName='DV', fontSize=10.5, leading=14)
    cellb = ParagraphStyle('cellb', fontName='DV-B', fontSize=10.5, leading=14)
    story = [Paragraph(title_lines[0], h1)] + [Paragraph(x, h2) for x in title_lines[1:]] + [Spacer(1, 0.5 * cm)]
    data = [[Paragraph(h, cellb) for h in table_headers]] + [[Paragraph(str(v), cell) for v in row] for row in table_rows]
    tbl = Table(data, repeatRows=1, hAlign='CENTER')
    tbl.setStyle(TableStyle([('GRID', (0, 0), (-1, -1), 0.5, colors.HexColor('#94a3b8')),
                             ('BACKGROUND', (0, 0), (-1, 0), colors.HexColor('#dbeafe')),
                             ('VALIGN', (0, 0), (-1, -1), 'MIDDLE'), ('TOPPADDING', (0, 0), (-1, -1), 5),
                             ('BOTTOMPADDING', (0, 0), (-1, -1), 5)]))
    story.append(tbl)
    story.append(Spacer(1, 0.5 * cm))
    for x in footer_lines:
        story.append(Paragraph(x, cell))
    doc.build(story)
    return Response(buf.getvalue(), media_type='application/pdf',
                    headers={'Content-Disposition': 'attachment; filename="%s"' % filename})

