# ---- Sao lưu & kiểm tra khôi phục (chỉ admin) ----

BACKUP_DIR = os.environ.get('BT_BACKUP_DIR') or os.path.join(BASE, '..', 'backups')

def _db_counts(path):
    c = sqlite3.connect('file:%s?mode=ro' % path, uri=True)
    out = {}
    for tbl in ('users', 'students', 'meal_absences', 'meal_closings'):
        try: out[tbl] = c.execute('SELECT COUNT(*) FROM %s' % tbl).fetchone()[0]
        except Exception: out[tbl] = None
    ok = c.execute('PRAGMA integrity_check').fetchone()[0] == 'ok'
    c.close()
    return out, ok

@app.post('/api/admin/backup')
async def admin_backup(req: Request):
    u, e = need_role(req, 'admin')
    if e: return e
    os.makedirs(BACKUP_DIR, exist_ok=True)
    name = 'ban-tru-%s.db' % now().strftime('%Y%m%d-%H%M%S')
    dest_path = os.path.join(BACKUP_DIR, name)
    src = db(); dst = sqlite3.connect(dest_path)
    src.backup(dst); dst.close(); src.close()
    counts, ok = _db_counts(dest_path)
    meta = {'file': name, 'created_at': now().isoformat(timespec='seconds'),
            'size': os.path.getsize(dest_path), 'counts': counts, 'integrity_ok': ok, 'by': u['username']}
    with open(os.path.join(BACKUP_DIR, name + '.json'), 'w', encoding='utf-8') as f:
        json.dump(meta, f, ensure_ascii=False)
    con = db(); audit(con, 'backup', 'ok', user=u, detail='Tạo sao lưu %s' % name, ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'backup': meta}

@app.get('/api/admin/backups')
async def admin_backups(req: Request):
    u, e = need_role(req, 'admin')
    if e: return e
    out = []
    if os.path.isdir(BACKUP_DIR):
        for fn in sorted(os.listdir(BACKUP_DIR), reverse=True):
            if fn.endswith('.db'):
                meta_path = os.path.join(BACKUP_DIR, fn + '.json')
                meta = {}
                if os.path.exists(meta_path):
                    with open(meta_path, encoding='utf-8') as f: meta = json.load(f)
                out.append({'file': fn, 'size': os.path.getsize(os.path.join(BACKUP_DIR, fn)), **meta})
    return {'ok': True, 'backups': out}

@app.post('/api/admin/restore-drill')
async def admin_restore_drill(req: Request):
    u, e = need_role(req, 'admin')
    if e: return e
    body = await req.json()
    name = os.path.basename(body.get('file') or '')
    src_path = os.path.join(BACKUP_DIR, name)
    if not name.endswith('.db') or not os.path.exists(src_path):
        return err(404, 'not_found', 'Không tìm thấy tệp sao lưu.')
    check_path = os.path.join(BACKUP_DIR, 'restore-check.db')
    src = sqlite3.connect('file:%s?mode=ro' % src_path, uri=True)
    dst = sqlite3.connect(check_path)
    src.backup(dst); dst.close(); src.close()
    counts, ok = _db_counts(check_path)
    meta = {}
    meta_path = src_path + '.json'
    if os.path.exists(meta_path):
        with open(meta_path, encoding='utf-8') as f: meta = json.load(f)
    match = all(counts.get(k) == v for k, v in (meta.get('counts') or {}).items())
    con = db(); audit(con, 'restore_drill', 'ok' if (ok and match) else 'fail', user=u,
                      detail='Kiểm tra khôi phục %s: toàn vẹn %s, số liệu khớp %s' % (name, ok, match),
                      ip=req.client.host if req.client else '')
    con.commit(); con.close()
    return {'ok': True, 'integrity_ok': ok, 'counts_match': match, 'counts': counts,
            'message': 'Khôi phục thử thành công: tệp sao lưu toàn vẹn và số liệu khớp với thời điểm sao lưu.'
                       if (ok and match) else 'Kiểm tra cho thấy có sai lệch — cần xem lại tệp sao lưu.'}



