SW_JS = "// Bán trú thông minh — service worker: tĩnh tải nhanh, dữ liệu luôn lấy mới từ máy chủ.\nconst CACHE = 'ban-tru-web-v11';\nself.addEventListener('install', e => { self.skipWaiting(); });\nself.addEventListener('activate', e => {\n  e.waitUntil(caches.keys().then(ks => Promise.all(ks.filter(k => k !== CACHE).map(k => caches.delete(k)))));\n});\nself.addEventListener('fetch', e => {\n  const url = new URL(e.request.url);\n  if (url.pathname.startsWith('/bantru/api/')) return; // dữ liệu nghiệp vụ: luôn qua mạng\n  if (url.pathname.startsWith('/bantru/static/')) {\n    e.respondWith(caches.match(e.request).then(hit => hit || fetch(e.request).then(r => {\n      const cp = r.clone(); caches.open(CACHE).then(c => c.put(e.request, cp)); return r;\n    })));\n    return;\n  }\n  e.respondWith(fetch(e.request).then(r => {\n    const cp = r.clone(); caches.open(CACHE).then(c => c.put(e.request, cp)); return r;\n  }).catch(() => caches.match(e.request)));\n});\n"
