@app.get('/')
async def bt_index():
    return _HTML(INDEX_HTML, headers={'Cache-Control': 'no-cache'})

@app.get('/manifest.webmanifest')
async def bt_manifest():
    return _Resp(MANIFEST_JSON, media_type='application/manifest+json')

@app.get('/sw.js')
async def bt_sw():
    return _Resp(SW_JS, media_type='application/javascript', headers={'Cache-Control': 'no-cache'})

@app.get('/assets/{name}')
async def bt_assets(name: str):
    if name not in ASSETS_B64:
        return _Resp('not found', status_code=404)
    return _Resp(_b64.b64decode(ASSETS_B64[name]), media_type=ASSETS_MEDIA[name],
                 headers={'Cache-Control': 'public, max-age=31536000, immutable'})

@app.get('/static/{name}')
async def bt_static(name: str):
    if name not in ICONS_B64:
        return _Resp('not found', status_code=404)
    return _Resp(_b64.b64decode(ICONS_B64[name]), media_type='image/png',
                 headers={'Cache-Control': 'public, max-age=86400'})

init_db()

def _bt_seed_admin_if_empty():
    """Lần đầu gắn lên web (CSDL trống): tạo sẵn 1 tài khoản quản trị với mật khẩu tạm,
    bắt buộc đổi ở lần đăng nhập đầu — các tài khoản còn lại do quản trị tạo trong ứng dụng."""
    con = db()
    try:
        n = con.execute('SELECT COUNT(*) AS n FROM users').fetchone()['n']
        if n == 0:
            cur = con.execute('INSERT INTO users(username,full_name,phone,password_hash,must_change_pw,created_at) '
                              'VALUES(?,?,?,?,?,?)',
                              ('admin', 'Quản trị hệ thống', '', ph.hash('Admin#2026'), 1,
                               now().isoformat(timespec='seconds')))
            con.execute('INSERT INTO user_roles(user_id,role_code,scope_class_code) VALUES(?,?,NULL)',
                        (cur.lastrowid, 'admin'))
            con.commit()
    finally:
        con.close()

_bt_seed_admin_if_empty()
